def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Locate separated foreground bands.
    active = [any(v != bg for v in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        end = r + 1
        while end < h and active[end]:
            end += 1
        bands.append((r, end))
        r = end

    # Compare equal-height bands and identify cells present in one but not
    # the other.
    pair = None
    for i in range(len(bands)):
        for j in range(i + 1, len(bands)):
            a0, a1 = bands[i]
            b0, b1 = bands[j]
            if a1 - a0 != b1 - b0:
                continue
            height = a1 - a0
            ma = [[grid[a0 + y][x] != bg for x in range(w)] for y in range(height)]
            mb = [[grid[b0 + y][x] != bg for x in range(w)] for y in range(height)]
            overlap = sum(ma[y][x] and mb[y][x]
                          for y in range(height) for x in range(w))
            if pair is None or overlap > pair[0]:
                pair = (overlap, a0, b0, ma, mb)

    if pair is None:
        return out

    _, a0, b0, ma, mb = pair
    height = len(ma)
    diffs = []
    for side, (source, target) in enumerate(((ma, mb), (mb, ma))):
        cells = {(y, x) for y in range(height) for x in range(w)
                 if source[y][x] and not target[y][x]}
        while cells:
            start = cells.pop()
            component = {start}
            stack = [start]
            while stack:
                y, x = stack.pop()
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (ny, nx) in cells:
                        cells.remove((ny, nx))
                        component.add((ny, nx))
                        stack.append((ny, nx))
            diffs.append((len(component), side, component))

    if not diffs:
        return out

    _, side, component = max(diffs, key=lambda item: item[0])
    target_start = b0 if side == 0 else a0
    for y, x in component:
        out[target_start + y][x] = 1
    return out
